1	'use strict';
2	// 「一键接入 / 移除 Claude Code 钩子」：合并写入用户的 settings.json。
3	//
4	// 这是本插件唯一会改用户 ~/.claude/settings.json 的地方（README 权限披露第 2 行）。
5	// 三条硬要求：写前备份、保留用户已有条目、卸载只摘自己那条。
6	// 自己的条目靠 command 里的绝对脚本路径识别（marker 字段会被 Claude Code 当未知字段，
7	// 但用户手改配置时容易丢，所以判定以 command 为准，marker 只做冗余标注）。
8	
9	const fs = require('fs');
10	const os = require('os');
11	const path = require('path');
12	
13	const { HOOKED_EVENTS } = require('./claude-events.js');
14	
15	const BACKUP_SUFFIX = '.bak-pet-agent-status';
16	// 写进 settings.json 的标记字段，方便用户在配置里一眼认出这几条是谁加的
17	const MARKER = 'pet-agent-status';
18	// 记在本插件条目里的「这个事件 key 是 install 现造的」标记。
19	// 卸载时据此决定该不该把 key 一并收回 —— 详见 CREATED_KEY 的用法注释。
20	const CREATED_KEY = 'petAgentStatusCreatedKey';
21	// 同理，记「hooks 这个容器本身是 install 现造的」。不能从「key 是不是全是本插件造的」
22	// 反推容器归属：用户留一个空 `hooks: {}` 时，7 个 key 全是本插件造的，反推会得出
23	// 「容器也是本插件的」而把用户的空容器删掉。归属只能显式记录，不能靠内容猜。
24	const CREATED_HOOKS = 'petAgentStatusCreatedHooks';
25	
26	function settingsPath() {
27	  const override = process.env.PET_AS_CLAUDE_SETTINGS;
28	  if (override) return override;
29	  return path.join(os.homedir(), '.claude', 'settings.json');
30	}
31	
32	// settings.json 里的 command 由 Claude Code 交给 shell 执行，路径含空格必须引起来。
33	// 宿主的插件落地目录在 `~/Library/Application Support/吐梨邦/plugins/` 之下（含空格），
34	// 裸拼会让 shell 把路径切成两个参数 → hook 以 MODULE_NOT_FOUND 退出并向 stderr 吐堆栈，
35	// 正好违反「绝不打扰会话」的初衷。用单引号包裹（POSIX 下单引号内除 `'` 外一律字面量），
36	// 路径自身含单引号时按 '\'' 惯例转义。
37	function shellQuote(s) {
38	  return `'${String(s).split("'").join("'\\''")}'`;
39	}
40	
41	// hook 脚本的绝对路径。插件目录会随安装位置变，所以每次现算，不写死。
42	function hookCommand() {
43	  const script = path.join(__dirname, '..', 'hooks', 'claude-status-hook.js');
44	  return `${shellQuote(process.execPath)} ${shellQuote(script)}`;
45	}
46	
47	// 读现有配置。文件不存在 = 空配置；文件损坏则抛（宁可让用户看到报错，也不能把
48	// 他手写的配置当空文件覆盖掉 —— 那是不可逆的数据丢失）。
49	function readSettings(file) {
50	  let raw;
51	  try {
52	    raw = fs.readFileSync(file, 'utf8');
53	  } catch (err) {
54	    if (err.code === 'ENOENT') return {};
55	    throw err;
56	  }
57	  if (raw.trim() === '') return {};
58	  const parsed = JSON.parse(raw);
59	  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
60	    throw new Error(`settings.json is not a JSON object: ${file}`);
61	  }
62	  return parsed;
63	}
64	
65	// 条目身份**只认 command**。别拿 MARKER 当身份判据：marker 是给人看的标注，
66	// 若按 marker 认领，卸载会连带删掉「同样带 marker 但 command 指向别处」的条目
67	// （多插件目录并存、或用户手抄了一条时就会踩到）。command 才是唯一真身份。
68	function isOurs(entry, command) {
69	  if (!entry || typeof entry !== 'object') return false;
70	  const hooks = Array.isArray(entry.hooks) ? entry.hooks : [];
71	  return hooks.some((h) => h && h.command === command);
72	}
73	
74	// 从一个分组里只摘掉本插件那一条 command，返回 { entry, removed }。
75	//
76	// 身份判据是分组内某条 command，那删除粒度就必须也是**那一条 command**，不能是整个分组。
77	// Claude Code 的 `hooks.<Event>[].hooks` 是数组，允许一组里挂多条命令；用户完全可能
78	// 把自己的命令追加进本插件写出的那个分组（配置里看着就是同一块，手改时最顺手）。
79	// 若按分组删，用户那条会被连带抹掉且毫无提示 —— 这是不可逆的用户配置丢失。
80	// entry 为 null 表示这个分组已经没有剩余命令，调用方应整条丢弃。
81	function stripOurCommand(entry, command) {
82	  const hooks = Array.isArray(entry.hooks) ? entry.hooks : [];
83	  const kept = hooks.filter((h) => !(h && h.command === command));
84	  const removed = hooks.length - kept.length;
85	  if (removed === 0) return { entry, removed: 0 };
86	  // 分组里除了我们没别的命令了 —— 整条丢弃，别在用户配置里留空壳分组
87	  if (kept.length === 0) return { entry: null, removed };
88	  // 还剩用户自己的命令：保住这个分组，只把我们那条摘掉。
89	  // 同时清掉 MARKER —— 分组已不再属于本插件，留着会让用户以为整组是插件的。
90	  const next = {};
91	  for (const key of Object.keys(entry)) {
92	    if (key === MARKER || key === CREATED_KEY || key === CREATED_HOOKS) continue;
93	    next[key] = key === 'hooks' ? kept : entry[key];
94	  }
95	  return { entry: next, removed };
96	}
97	
98	// 从事件列表里摘掉本插件的 command（保住同组内用户自己的命令），
99	// 返回 { list, removed, createdKey, createdHooks }。install（幂等去重）与 uninstall
100	// 共用同一套摘除逻辑，避免两处粒度再次跑偏。
101	// createdKey / createdHooks：被摘掉的条目里标着「这个事件 key / hooks 容器是本插件造的」，
102	// 供 uninstall 决定收不收 key 与容器。
103	function stripFromList(list, command) {
104	  const kept = [];
105	  let removed = 0;
106	  let createdKey = false;
107	  let createdHooks = false;
108	  for (const entry of list) {
109	    if (!isOurs(entry, command)) { kept.push(entry); continue; }
110	    if (entry[CREATED_KEY] === true) createdKey = true;
111	    if (entry[CREATED_HOOKS] === true) createdHooks = true;
112	    const res = stripOurCommand(entry, command);
113	    removed += res.removed;
114	    if (res.entry !== null) kept.push(res.entry);
115	  }
116	  return { list: kept, removed, createdKey, createdHooks };
117	}
118	
119	// 原子写：同目录 tmp + rename，理由同 state-files.js —— 半截 settings.json 会让
120	// Claude Code 起不来，这是用户配置，比状态文件更输不起。
121	function writeSettings(file, data) {
122	  fs.mkdirSync(path.dirname(file), { recursive: true });
123	  const tmp = path.join(path.dirname(file), `.${path.basename(file)}.tmp-${process.pid}-${Math.random().toString(36).slice(2, 8)}`);
124	  try {
125	    fs.writeFileSync(tmp, `${JSON.stringify(data, null, 2)}\n`, 'utf8');
126	    fs.renameSync(tmp, file);
127	  } catch (err) {
128	    try { fs.unlinkSync(tmp); } catch (_) { /* 清理失败无所谓 */ }
129	    throw err;
130	  }
131	}
132	
133	// 备份原文件。只在原文件存在时备份，且**已存在的备份绝不覆盖**。
134	//
135	// 备份的唯一用途是「回滚到本插件动手之前」。若每次 install/uninstall 都刷新备份，
136	// 第二次点接入就会把备份刷成「已含本插件 7 条钩子」的版本 —— 用户 cp 回去后
137	// isInstalled 仍为 true，备份丧失全部意义且无从察觉。首份即是接入前原文，保住它。
138	function backup(file) {
139	  if (!fs.existsSync(file)) return null;
140	  const dest = file + BACKUP_SUFFIX;
141	  if (fs.existsSync(dest)) return dest; // 首份不覆盖
142	  fs.copyFileSync(file, dest);
143	  return dest;
144	}
145	
146	// createdKey 表示「这个事件 key 在 install 之前不存在，是本插件现造的」。
147	// 只有这种 key 才允许在卸载时连 key 一起收回；用户原有的 key 一律还给用户。
148	function ourEntry(command, createdKey, createdHooks) {
149	  const entry = { [MARKER]: true, hooks: [{ type: 'command', command }] };
150	  if (createdKey) entry[CREATED_KEY] = true;
151	  if (createdHooks) entry[CREATED_HOOKS] = true;
152	  return entry;
153	}
154	
155	// 上一轮装的条目里带没带某个创建标记 —— 幂等重装时要沿用首次安装的判断，
156	// 不能按「本次安装前在不在」重算：那时 key/容器已经被上一次 install 造出来了，
157	// 重算必然得出 false，卸载就再也收不回自己造的东西（变成留空壳）。
158	function hadFlag(list, command, flag) {
159	  return list.some((e) => isOurs(e, command) && e[flag] === true);
160	}
161	
162	function install(options) {
163	  const file = (options && options.settingsFile) || settingsPath();
164	  const command = (options && options.command) || hookCommand();
165	  const settings = readSettings(file);
166	  const backupFile = backup(file);
167	
168	  // 用户原本有没有 hooks 这个容器。没有则是本插件现造的，卸载时要连容器一起收回；
169	  // 有（哪怕是空对象 {}）就是用户的配置内容，卸载后必须原样还回去。
170	  const hooksExisted = Object.prototype.hasOwnProperty.call(settings, 'hooks')
171	    && settings.hooks && typeof settings.hooks === 'object' && !Array.isArray(settings.hooks);
172	  if (!hooksExisted) settings.hooks = {};
173	
174	  let added = 0;
175	  for (const event of HOOKED_EVENTS) {
176	    const existed = Object.prototype.hasOwnProperty.call(settings.hooks, event);
177	    const list = Array.isArray(settings.hooks[event]) ? settings.hooks[event] : [];
178	    // 幂等：先摘掉已有的自己（只摘 command 粒度，保住同组内用户的命令）再追加
179	    // —— 否则每次点接入都多一条，事件触发 N 次。
180	    const { list: kept, removed } = stripFromList(list, command);
181	    // 是不是本插件造的：首次安装看原本在不在；重装沿用上次的标记。
182	    const createdKey = removed > 0 ? hadFlag(list, command, CREATED_KEY) : !existed;
183	    const createdHooks = removed > 0 ? hadFlag(list, command, CREATED_HOOKS) : !hooksExisted;
184	    kept.push(ourEntry(command, createdKey, createdHooks));
185	    if (removed === 0) added++;
186	    settings.hooks[event] = kept;
187	  }
188	
189	  writeSettings(file, settings);
190	  return { file, backupFile, command, events: HOOKED_EVENTS.slice(), added, hooksExisted };
191	}
192	
193	function uninstall(options) {
194	  const file = (options && options.settingsFile) || settingsPath();
195	  const command = (options && options.command) || hookCommand();
196	  let settings;
197	  try {
198	    settings = readSettings(file);
199	  } catch (err) {
200	    if (err.code === 'ENOENT') return { file, backupFile: null, removed: 0 };
201	    throw err;
202	  }
203	  if (!settings.hooks || typeof settings.hooks !== 'object' || Array.isArray(settings.hooks)) {
204	    return { file, backupFile: null, removed: 0 };
205	  }
206	
207	  const backupFile = backup(file);
208	  let removed = 0;
209	  // hooks 容器本身是不是本插件造的（读自条目上的显式标记，不从 key 归属反推）。
210	  let createdHooks = false;
211	  for (const event of Object.keys(settings.hooks)) {
212	    const list = settings.hooks[event];
213	    if (!Array.isArray(list)) continue;
214	    const res = stripFromList(list, command);
215	    removed += res.removed;
216	    if (res.createdHooks) createdHooks = true;
217	    // 删 key 的唯一条件：这个 key 是**本插件 install 时现造的**，且摘完已空。
218	    //
219	    // 别退回「空了就删」—— 那个判据与「是谁创建的」无关，会把用户原有的空数组键
220	    // （`PreCompact: []` 之类的占位/临时停用写法）静默删掉。空数组不是垃圾，是用户
221	    // 的配置内容；本插件只有权收回自己造的东西。这与「删除粒度 = 身份粒度」是同一条
222	    // 铁律，只是提高了一个容器层级：条目层认 command，key 层认 createdKey。
223	    if (res.createdKey && res.list.length === 0) delete settings.hooks[event];
224	    else settings.hooks[event] = res.list;
225	  }
226	  // hooks 容器同理：只有本插件造的容器才收回，用户原有的空 `hooks: {}` 原样还回去。
227	  if (createdHooks && Object.keys(settings.hooks).length === 0) delete settings.hooks;
228	
229	  writeSettings(file, settings);
230	  return { file, backupFile, removed };
231	}
232	
233	// 面板要显示「已接入 ✓ / 一键接入」两种状态，靠这个判定
234	function isInstalled(options) {
235	  const file = (options && options.settingsFile) || settingsPath();
236	  const command = (options && options.command) || hookCommand();
237	  let settings;
238	  try { settings = readSettings(file); } catch (_) { return false; }
239	  const hooks = settings.hooks;
240	  if (!hooks || typeof hooks !== 'object' || Array.isArray(hooks)) return false;
241	  return HOOKED_EVENTS.every((event) => {
242	    const list = hooks[event];
243	    return Array.isArray(list) && list.some((entry) => isOurs(entry, command));
244	  });
245	}
246	
247	module.exports = {
248	  BACKUP_SUFFIX, MARKER, CREATED_KEY, CREATED_HOOKS,
249	  settingsPath, hookCommand, readSettings, writeSettings,
250	  install, uninstall, isInstalled
251	};
252

