1	'use strict';
2	// 采集器状态机：状态文件快照 → panel 渲染行（PROTOCOL.md「采集器推导态」的唯一实现处）。
3	//
4	// 全纯函数：now / isPidAlive 一律由调用方注入，测试不 sleep、不探真实进程。
5	// 推导态 error/idle/unknown 只活在这里与面板，绝不落盘（协议红线）。
6	
7	const ERROR_STALE_MS = 60 * 1000;        // running/waiting 超过这么久没心跳才考虑 error
8	const IDLE_MS = 20 * 60 * 1000;          // 任何状态超过这么久算 idle
9	const DROP_IDLE_MS = 20 * 60 * 1000;     // idle 超过这么久从面板移除
10	
11	// 副行文案的 locale key（DESIGN.md 状态图例；unknown 与 idle 必须不同词，绝不误报完成）
12	const SUBLINE_KEY = {
13	  running: 'state.running',
14	  waiting: 'state.waiting',
15	  done: 'state.done',
16	  ended: 'state.ended',
17	  error: 'state.error',
18	  idle: 'state.idle',
19	  unknown: 'state.unknown'
20	};
21	
22	// 会话形态：本轮只有 CLI（Codex App 任务是二期，见 docs/prd.md 非目标）
23	function formOf(rec) {
24	  return rec && rec.form === 'app' ? 'app' : 'cli';
25	}
26	
27	/**
28	 * 单条记录 → 展示态。落盘只有 running/waiting/done/ended 四种，其余都在这里推。
29	 * @param {object} rec 已通过 validateRecord 的记录
30	 * @param {number} now 注入的当前毫秒
31	 * @param {(pid:number)=>boolean} isPidAlive 注入的存活探测
32	 */
33	function deriveState(rec, now, isPidAlive) {
34	  const age = now - rec.ts;
35	  // error 优先于 idle：进程已经不在了，比「久没动静」更有信息量（PROTOCOL.md 推导态第 1 条）
36	  if ((rec.state === 'running' || rec.state === 'waiting')
37	      && age > ERROR_STALE_MS
38	      && rec.pid != null
39	      && !isPidAlive(rec.pid)) {
40	    return 'error';
41	  }
42	  if (rec.state === 'done' || rec.state === 'ended') return 'idle';
43	  if (age > IDLE_MS) return 'idle';
44	  return rec.state;
45	}
46	
47	// running 行显 mm:ss 计时（DESIGN.md 右列）；其余显相对时间
48	function formatTime(state, ageMs, t) {
49	  if (state === 'running' || state === 'waiting') {
50	    const total = Math.max(0, Math.floor(ageMs / 1000));
51	    const mm = String(Math.floor(total / 60)).padStart(2, '0');
52	    const ss = String(total % 60).padStart(2, '0');
53	    return `${mm}:${ss}`;
54	  }
55	  const minutes = Math.floor(Math.max(0, ageMs) / 60000);
56	  return minutes < 1 ? t('time.justNow') : t('time.minutesAgo', { n: minutes });
57	}
58	
59	/**
60	 * 这条记录是从哪一刻开始算 idle 的。
61	 *
62	 * 两种入 idle 的路径起点不同，不能都拿 ts 当起点：
63	 * - done/ended：写入那一刻就完成了，idle 从 `ts` 起算；
64	 * - running/waiting 熬过 20min：那 20min 里它还在「运行中」显示着，
65	 *   idle 从 `ts + IDLE_MS` 起算，否则一个刚超时的 running 会被当成
66	 *   「已经 idle 了 20 分钟」当场移除，用户眼前的行凭空消失。
67	 */
68	function idleSince(rec) {
69	  return (rec.state === 'done' || rec.state === 'ended') ? rec.ts : rec.ts + IDLE_MS;
70	}
71	
72	// 排序：waiting 恒置顶（组内 ts 降序），其余 ts 降序（DESIGN.md「排序规则」）
73	function sortRows(rows) {
74	  return rows.slice().sort((a, b) => {
75	    const aw = a.state === 'waiting' ? 0 : 1;
76	    const bw = b.state === 'waiting' ? 0 : 1;
77	    if (aw !== bw) return aw - bw;
78	    return b.ts - a.ts;
79	  });
80	}
81	
82	// 取词兜底：没注入 i18n 时返回 key，界面上一眼看出漏词（与 lib/i18n.js 同策略）
83	function fallbackT(key) { return key; }
84	
85	// 跳转判定抛错不该打死整轮采集（它要 spawn ps，什么都可能发生）；抛了就当不能跳。
86	function safeCanJump(fn, tty) {
87	  try { return fn(tty); } catch (_) { return false; }
88	}
89	
90	/**
91	 * 快照 → { rows, summary }。
92	 * @param {{records:object[], unknown?:object[]}} snapshot lib/state-files.js#readSnapshots 的返回值
93	 * @param {{now:number, isPidAlive:Function, t?:Function, canJump?:Function, jumpErrors?:object}} opts
94	 *   canJump：注入的「这个 tty 能不能跳」判定。**aggregate 自己绝不判终端归属** ——
95	 *   判定唯一实现在 lib/terminal-jump.js#detectTerminal（criteria §2「只此一处」）。
96	 *   缺省恒 false：拿不到判定就不给入口，好过给一个点了没反应的假入口。
97	 *   jumpErrors：sessionId → 错误文案，上一次跳转失败经快照回推（DESIGN.md 行内错误条）。
98	 */
99	function aggregate(snapshot, opts) {
100	  const o = opts || {};
101	  const now = Number.isFinite(o.now) ? o.now : Date.now();
102	  const isPidAlive = typeof o.isPidAlive === 'function' ? o.isPidAlive : () => true;
103	  const t = typeof o.t === 'function' ? o.t : fallbackT;
104	  const canJump = typeof o.canJump === 'function' ? o.canJump : () => false;
105	  const jumpErrors = (o.jumpErrors && typeof o.jumpErrors === 'object') ? o.jumpErrors : null;
106	
107	  const records = (snapshot && Array.isArray(snapshot.records)) ? snapshot.records : [];
108	  const badFiles = (snapshot && Array.isArray(snapshot.unknown)) ? snapshot.unknown : [];
109	
110	  const rows = [];
111	  for (const rec of records) {
112	    const state = deriveState(rec, now, isPidAlive);
113	    if (state === 'idle' && now - idleSince(rec) > DROP_IDLE_MS) continue;
114	    const row = makeRow(rec, state, now, t);
115	    // 跳转入口标志：tty 拿不到、或推断不出终端归属 → false，panel 不渲染可点态。
116	    row.canJump = rec.tty != null && !!safeCanJump(canJump, rec.tty);
117	    if (jumpErrors && typeof jumpErrors[rec.sessionId] === 'string') {
118	      row.jumpError = jumpErrors[rec.sessionId];
119	    }
120	    rows.push(row);
121	  }
122	
123	  // 损坏/schema 过高的文件也要有一行，否则用户看不出「有个会话读不了」——
124	  // 但状态是 unknown，绝不当 done（PROTOCOL.md 硬要求）。
125	  for (const bad of badFiles) {
126	    rows.push({
127	      sessionId: sessionIdOfFile(bad.file),
128	      agent: 'claude-code',
129	      form: 'cli',
130	      project: sessionIdOfFile(bad.file),
131	      state: 'unknown',
132	      raw: 'unknown',   // 读都读不出来，没有可信的落盘状态；绝不留空让联动误判
133	      subline: t(SUBLINE_KEY.unknown),
134	      timeText: '',
135	      ts: 0,
136	      tty: null,
137	      pid: null,
138	      cwd: '',
139	      canJump: false,   // 文件都读不出来，哪来的 tty
140	      reason: bad.reason || 'unknown'
141	    });
142	  }
143	
144	  const sorted = sortRows(rows);
145	  return {
146	    rows: sorted,
147	    summary: {
148	      running: sorted.filter((r) => r.state === 'running').length,
149	      waiting: sorted.filter((r) => r.state === 'waiting').length,
150	      total: sorted.length,
151	      unknown: sorted.filter((r) => r.state === 'unknown').length
152	    }
153	  };
154	}
155	
156	// 行结构：panel 直接渲染，不再算业务字段（criteria §2 最后一条）
157	function makeRow(rec, state, now, t) {
158	  const row = {
159	    sessionId: rec.sessionId,
160	    agent: rec.agent,
161	    form: formOf(rec),
162	    project: rec.project,
163	    state,
164	    // 落盘的原始状态。panel 只看 state（展示态），联动看 raw ——
165	    // done/ended 的展示态是 idle（灰、随后淡出），但「刚办完」是个**迁移**，
166	    // 宠物要在这一刻喊。只留 state 的话 done 永远被 idle 盖住，
167	    // DESIGN.md 的完成提醒就成了永不触发的死代码。
168	    raw: rec.state,
169	    subline: t(SUBLINE_KEY[state] || SUBLINE_KEY.unknown),
170	    timeText: formatTime(state, now - rec.ts, t),
171	    ts: rec.ts,
172	    tty: rec.tty == null ? null : rec.tty,
173	    pid: rec.pid == null ? null : rec.pid,
174	    cwd: rec.cwd
175	  };
176	  if (rec.threadId != null) row.threadId = rec.threadId;
177	  return row;
178	}
