180	// 坏文件没有可信的 sessionId（正文都解析不出来），只能拿文件名当标识
181	function sessionIdOfFile(file) {
182	  const name = String(file == null ? '' : file);
183	  const base = name.slice(name.lastIndexOf('/') + 1);
