1	'use strict';
2	// tool 入口：宿主 utilityProcess 里跑，activate(pet) 收到 SDK 对象。
3	// 职责只有三件：定时读状态目录 → aggregate 推导 → 经 events 推给 panel，顺带触发宠物联动。
4	//
5	// 合规通道：manifest 声明的 pet.{scheduler,events,pet} + 状态目录读写（README 权限披露）。
6	
7	const path = require('path');
8	
9	const LIB = path.join(__dirname, '..', 'lib');
10	const stateFiles = require(path.join(LIB, 'state-files.js'));
11	const { aggregate } = require(path.join(LIB, 'aggregate.js'));
12	const { createPetLink } = require(path.join(LIB, 'pet-link.js'));
13	const { createNodeI18n } = require(path.join(LIB, 'i18n.js'));
14	const installer = require(path.join(LIB, 'claude-hooks-installer.js'));
15	const terminalJump = require(path.join(LIB, 'terminal-jump.js'));
16	
17	const TICK_MS = 2000;                            // 宿主把最小间隔钳到 1000ms，2s 满足「3 秒内可感知」
18	// 事件名带前缀防撞（AGENTS.md 惯例）。这一组与 panel/panel.html 里的常量是**两份副本**，
19	// 改一处必须改两处；tests/panel-dom-test.js 与 tool-lifecycle-test.js 各自断言了名字，
20	// 漂移会在门禁里红。
21	const SNAPSHOT_EVENT = 'agent-status:snapshot';
22	const INSTALL_STATE_EVENT = 'agent-status:install-state';   // tool → panel：接入与否
23	const INSTALL_CLAUDE_EVENT = 'agent-status:install-claude';   // panel → tool：接入意图
24	const UNINSTALL_CLAUDE_EVENT = 'agent-status:uninstall-claude'; // panel → tool：移除意图
25	const JUMP_EVENT = 'agent-status:jump';                         // panel → tool：跳回终端意图
26	
27	// 跳转失败的错误条挂多久。留到下一次跳转成功/超时为止，不能永远挂着 ——
28	// 用户在别处修好终端后面板还红着，会以为坏了。
29	const JUMP_ERROR_TTL_MS = 30 * 1000;
30	// 进程表（ps）缓存窗口。canJump 是每行每 tick 都要问的，而终端归属几分钟内不会变；
31	// 不缓存的话 2s 一轮 × N 行会 spawn 一堆 ps。
32	const PS_CACHE_MS = 10 * 1000;
33	
34	// 进程存活探测：kill(pid, 0) 不发信号只查存在性。EPERM = 存在但不属于本用户，算存活。
35	function isPidAlive(pid) {
36	  try { process.kill(pid, 0); return true; } catch (err) { return err && err.code === 'EPERM'; }
37	}
38	
39	/**
40	 * 造一个采集器。所有外部依赖可注入，测试不碰真实目录/时钟/进程。
41	 * @param {object} [deps] { dir, now, isPidAlive, t, playAnimGuard, readSnapshots }
42	 */
43	function createCollector(deps) {
44	  const d = deps || {};
45	  const readSnapshots = typeof d.readSnapshots === 'function' ? d.readSnapshots : stateFiles.readSnapshots;
46	  const now = typeof d.now === 'function' ? d.now : () => Date.now();
47	  const alive = typeof d.isPidAlive === 'function' ? d.isPidAlive : isPidAlive;
48	  // 语言只认这一处。副行/时间文案由 tool 取词后随行下发，panel 的静态文案则按
49	  // 快照里带的 locale 取 —— 两边各猜各的会当场撞车：tool 看 LANG、panel 看
50	  // navigator.language，两者不一致时同一块面板上半截中文下半截英文。
51	  const i18n = createNodeI18n(d.locale);
52	  const t = typeof d.t === 'function' ? d.t : i18n.t;
53	  const locale = d.locale || i18n.locale;
54	  const link = createPetLink({ playAnimGuard: d.playAnimGuard });
55	  // 缺省 undefined → installer 自己走 settingsPath()（即 PET_AS_CLAUDE_SETTINGS 覆盖）；
56	  // 测试注入临时文件，绝不碰真实 ~/.claude/settings.json
57	  const installOpts = d.settingsFile ? { settingsFile: d.settingsFile } : undefined;
58	
59	  let taskId = null;
60	  let lastSnapshot = { rows: [], summary: { running: 0, waiting: 0, total: 0, unknown: 0 } };
61	
62	  // ---- 跳转（US-005）----
63	  // psTree/runner 可注入：测试绝不 spawn ps、更不真跑 osascript（会骚扰真实桌面）。
64	  // 数组或函数都收（terminal-jump 两种都吃）：测试注数组最省事，注函数可模拟 ps 变化
65	  const psTree = (typeof d.psTree === 'function' || Array.isArray(d.psTree)) ? d.psTree : null;
66	  const jumpRunner = typeof d.jumpRunner === 'function' ? d.jumpRunner : undefined;
67	  const jumpErrors = new Map();   // sessionId → { text, at }
68	  let psCache = null;             // { at, list } —— 见 PS_CACHE_MS
69	
70	  // 进程表读一次给一轮里所有行共用。terminal-jump 接受「函数或数组」，这里给数组。
71	  function psTreeCached(at) {
72	    if (psTree) return psTree;   // 注入的自己管缓存
73	    if (psCache && at - psCache.at < PS_CACHE_MS) return psCache.list;
74	    let list = [];
75	    try { list = terminalJump.readPsTree(); } catch (_) { list = []; }
76	    psCache = { at, list };
77	    return list;
78	  }
79	
80	  // canJump 判定：委托给 lib/terminal-jump.js（归属判定唯一实现处），本文件不自己判。
81	  function makeCanJump(at) {
82	    const tree = psTreeCached(at);
83	    return (tty) => terminalJump.detectTerminal(tty, tree) != null;
84	  }
85	
86	  // 当前有效的行内错误（过了 TTL 就忘掉）
87	  function activeJumpErrors(at) {
88	    const out = {};
89	    for (const [id, entry] of [...jumpErrors.entries()]) {
90	      if (at - entry.at >= JUMP_ERROR_TTL_MS) { jumpErrors.delete(id); continue; }
91	      out[id] = entry.text;
92	    }
93	    return out;
94	  }
95	
96	  /**
97	   * panel 点了某一行。查它的 tty → 生成脚本 → 执行；失败**不 throw 不静默**，
98	   * 错误文案存起来随下一次快照回推，面板在该行下方显示行内错误条（DESIGN.md）。
99	   */
100	  function handleJump(pet, data) {
101	    const at = now();
102	    const sessionId = data && data.sessionId;
103	    if (!sessionId) return { ok: false, reason: 'unavailable' };
104	    const row = lastSnapshot.rows.find((r) => r.sessionId === sessionId);
105	    let result;
106	    if (!row || row.tty == null) {
107	      result = { ok: false, reason: 'unavailable' };
108	    } else {
109	      result = terminalJump.runJump(row.tty, { psTree: psTreeCached(at), runner: jumpRunner });
110	    }
111	    if (result.ok) {
112	      jumpErrors.delete(sessionId);
113	    } else {
114	      // reason==='unavailable' 是「压根找不到终端」，与「osascript 报错」文案不同：
115	      // 前者用户该去别处找会话，后者是这次执行挂了，可以再试。
116	      const text = result.reason === 'unavailable'
117	        ? t('jump.unavailable')
118	        : t('jump.failed', { reason: result.reason });
119	      jumpErrors.set(sessionId, { text, at });
120	    }
121	    // 立刻回推一轮，用户点完当场看到结果，不用等下一个 tick
122	    tick(pet);
123	    return result;
124	  }
125	
126	  // 一轮采集。整体包 try/catch：抛出去会打死宿主定时任务，下一轮就没了。
127	  function tick(pet) {
128	    try {
129	      const at = now();
130	      const raw = readSnapshots(d.dir);
131	      const result = aggregate(raw, {
132	        now: at, isPidAlive: alive, t,
133	        canJump: makeCanJump(at),          // 判定实现在 lib/terminal-jump.js，这里只注入
134	        jumpErrors: activeJumpErrors(at)   // 上次跳转失败的行内错误条
135	      });
136	      // locale 随快照下发，panel 据此选词表（契约仍是 {rows, summary}，locale 是附加字段）
137	      result.locale = locale;
138	      lastSnapshot = result;
139	      emit(pet, SNAPSHOT_EVENT, result);
140	      // 接入态随每轮一起推：面板是随开随关的，start 时推一次的话，
141	      // 之后才打开的面板永远等不到这条，空态会一直停在「一键接入」——
142	      // 哪怕钩子早就装好了。读一个小 JSON，2s 一次的开销可以忽略。
143	      pushInstallState(pet);
144	      link.onSnapshot(result.rows, pet, { now: at, t });
145	      return result;
146	    } catch (_) {
147	      return lastSnapshot;   // 本轮读坏了就沿用上轮，面板不闪空
148	    }
149	  }
150	
151	  // panel 的接入按钮只发意图，改配置的活在这边（panel 上下文没有 fs，也不该有）。
152	  // 每次改完立刻回推一次接入态，面板的「一键接入 / 已接入 ✓」当场翻面。
153	  function pushInstallState(pet) {
154	    let claude = false;
155	    try { claude = installer.isInstalled(installOpts); } catch (_) { claude = false; }
156	    emit(pet, INSTALL_STATE_EVENT, { claude });
157	    return claude;
158	  }
159	
160	  function handleInstall(pet) {
161	    // 改用户 settings.json 失败不该打死采集器：面板照旧显示「未接入」，用户可再试。
162	    try { installer.install(installOpts); } catch (_) { /* 权限/磁盘问题 */ }
163	    return pushInstallState(pet);
164	  }
165	
166	  function handleUninstall(pet) {
167	    try { installer.uninstall(installOpts); } catch (_) { /* 同上 */ }
168	    return pushInstallState(pet);
169	  }
170	
171	  async function start(pet) {
172	    if (taskId != null) return taskId;   // 启停串行，不重复注册（重复注册 = 泄漏定时器）
173	    // 先接意图再起定时器：面板可能在 tick 之前就点了接入
174	    subscribe(pet, INSTALL_CLAUDE_EVENT, () => handleInstall(pet));
175	    subscribe(pet, UNINSTALL_CLAUDE_EVENT, () => handleUninstall(pet));
176	    subscribe(pet, JUMP_EVENT, (data) => handleJump(pet, data));
177	    // 必须 await：pet.scheduler.every 返回的是 Promise<taskId>，
178	    // 直接存 Promise 会让 cancel 拿到个对象、恒 miss，旧定时器永不回收（宿主已知坑）。
179	    taskId = await pet.scheduler.every(TICK_MS, () => tick(pet));
180	    tick(pet);   // 立刻来一轮，用户开面板不用等 2 秒
181	    return taskId;
182	  }
183	
184	  async function stop(pet) {
185	    if (taskId == null) return;
186	    const id = taskId;
187	    taskId = null;   // 先清再 cancel：cancel 失败也不该留个假 id 挡住下次 start
188	    try { await pet.scheduler.cancel(id); } catch (_) { /* 宿主已经收走了 */ }
189	  }
190	
191	  return {
192	    start, stop, tick,
193	    handleInstall, handleUninstall, pushInstallState, handleJump,
194	    get taskId() { return taskId; },
195	    get lastSnapshot() { return lastSnapshot; }
196	  };
197	}
198	
199	function emit(pet, name, data) {
200	  try {
201	    if (pet && pet.events && typeof pet.events.emit === 'function') pet.events.emit(name, data);
