272	    var isCodex = row.agent === 'codex';
273	    var badge = document.createElement('span');
274	    badge.className = 'badge ' + (isCodex ? 'is-codex' : 'is-claude');
275	
276	    var svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
