334	  function render(snapshot) {
335	    var rows = (snapshot && Array.isArray(snapshot.rows)) ? snapshot.rows : [];
336	    var summary = (snapshot && snapshot.summary) || {};
337	
338	    // tool 说了算：语言一变就把静态文案重刷一遍，别和行内文案打架
339	    if (snapshot && CATALOGS[snapshot.locale] && snapshot.locale !== locale) {
340	      locale = snapshot.locale;
341	      paintStatic();
342	    }
343	
344	    elList.textContent = '';
345	    for (var i = 0; i < rows.length; i++) {
346	      var row = rows[i];
