1	'use strict';
2	// 状态文件读写（PROTOCOL.md schema:1 的唯一实现处）。
3	// 只碰状态目录：默认 ~/.local/state/pet-agent-status/，测试经 PET_AGENT_STATUS_DIR 覆盖。
4	
5	const fs = require('fs');
6	const os = require('os');
7	const path = require('path');
8	
9	const SCHEMA = 1;
10	const AGENTS = ['claude-code', 'codex'];
11	const STATES = ['running', 'waiting', 'done', 'ended'];
12	const SOURCES = ['hook', 'ipc', 'reconcile'];
13	
14	// PROTOCOL.md「字段」表里必填的那些；缺任意一项按损坏跳过。
15	const REQUIRED = ['schema', 'agent', 'sessionId', 'cwd', 'project', 'tty', 'pid', 'state', 'lastEvent', 'ts'];
16	
17	function stateDir() {
18	  const override = process.env.PET_AGENT_STATUS_DIR;
19	  if (override) return override;
20	  return path.join(os.homedir(), '.local', 'state', 'pet-agent-status');
21	}
22	
23	// 防路径穿越：PROTOCOL.md 规定只留 [A-Za-z0-9._-]，其余一律 _
24	function sanitizeSessionId(sessionId) {
25	  const s = String(sessionId == null ? '' : sessionId);
26	  const cleaned = s.replace(/[^A-Za-z0-9._-]/g, '_');
27	  return cleaned === '' ? '_' : cleaned;
28	}
29	
30	function fileFor(sessionId, dir) {
31	  return path.join(dir || stateDir(), `${sanitizeSessionId(sessionId)}.json`);
32	}
33	
34	// 组装一条符合 schema:1 的记录。调用方给什么就写什么，缺省项补协议要求的 null。
35	function buildRecord(input) {
36	  const cwd = String(input.cwd == null ? '' : input.cwd);
37	  const rec = {
38	    schema: SCHEMA,
39	    agent: input.agent,
40	    sessionId: sanitizeSessionId(input.sessionId),
41	    cwd,
42	    project: input.project != null ? String(input.project) : path.basename(cwd),
43	    tty: input.tty != null ? String(input.tty) : null,
44	    pid: Number.isFinite(input.pid) ? Number(input.pid) : null,
45	    state: input.state,
46	    lastEvent: String(input.lastEvent == null ? '' : input.lastEvent),
47	    ts: Number.isFinite(input.ts) ? Number(input.ts) : Date.now()
48	  };
49	  if (input.threadId != null) rec.threadId = String(input.threadId);
50	  rec.source = SOURCES.includes(input.source) ? input.source : 'hook';
51	  return rec;
52	}
53	
54	// 原子写：同目录临时文件 → rename 覆盖（同分区，rename 保证读者永远看到完整 JSON）。
55	// 临时文件名以 .tmp 结尾（不是 .json），因此天然落在 readSnapshots 的 .json 过滤之外；
56	// 读侧不得靠前缀识别临时文件——`.tmp-xxx` 是协议允许的合法 sessionId，靠前缀会误杀真会话。
57	function writeStatus(input, dir) {
58	  const target = dir || stateDir();
59	  fs.mkdirSync(target, { recursive: true });
60	  const rec = buildRecord(input);
61	  const file = path.join(target, `${rec.sessionId}.json`);
62	  const tmp = path.join(target, `.tmp-${rec.sessionId}-${process.pid}-${Math.random().toString(36).slice(2, 8)}.tmp`);
63	  try {
64	    fs.writeFileSync(tmp, `${JSON.stringify(rec)}\n`, 'utf8');
65	    fs.renameSync(tmp, file);
66	  } catch (err) {
67	    try { fs.unlinkSync(tmp); } catch (_) { /* 清理失败无所谓 */ }
68	    throw err;
69	  }
70	  return { file, record: rec };
71	}
72	
73	// 校验一条已解析的记录是否可用；不可用返回原因（调用方归 unknown 计数）
74	function validateRecord(obj) {
75	  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return 'not-an-object';
76	  if (obj.schema !== SCHEMA) {
77	    return Number.isFinite(obj.schema) && obj.schema > SCHEMA ? 'schema-too-new' : 'schema-mismatch';
78	  }
79	  for (const key of REQUIRED) {
80	    if (!(key in obj)) return `missing:${key}`;
81	  }
82	  if (!AGENTS.includes(obj.agent)) return 'bad-agent';
83	  if (!STATES.includes(obj.state)) return 'bad-state';
84	  if (typeof obj.sessionId !== 'string' || obj.sessionId === '') return 'bad-sessionId';
85	  if (typeof obj.cwd !== 'string') return 'bad-cwd';
86	  if (typeof obj.project !== 'string') return 'bad-project';
87	  if (obj.tty !== null && typeof obj.tty !== 'string') return 'bad-tty';
88	  if (obj.pid !== null && !Number.isFinite(obj.pid)) return 'bad-pid';
89	  if (typeof obj.lastEvent !== 'string') return 'bad-lastEvent';
90	  if (!Number.isFinite(obj.ts)) return 'bad-ts';
91	  return null;
92	}
93	
94	// 读整个目录 → 快照数组。任何单文件问题都只归类计数，绝不抛（采集器每 2s 调一次，不许被脏文件打死）。
95	function readSnapshots(dir) {
96	  const target = dir || stateDir();
97	  const records = [];
98	  const unknown = [];
99	  let names;
100	  try {
101	    names = fs.readdirSync(target);
102	  } catch (_) {
103	    return { records, unknown, unknownCount: 0 };
104	  }
105	  for (const name of names) {
106	    if (!name.endsWith('.json')) continue;
107	    const file = path.join(target, name);
108	    let parsed;
109	    try {
110	      parsed = JSON.parse(fs.readFileSync(file, 'utf8'));
111	    } catch (_) {
112	      unknown.push({ file, reason: 'unparsable' });
113	      continue;
114	    }
115	    const reason = validateRecord(parsed);
116	    if (reason) { unknown.push({ file, reason }); continue; }
117	    records.push(parsed);
118	  }
119	  return { records, unknown, unknownCount: unknown.length };
120	}
121	
122	function readStatus(sessionId, dir) {
123	  const file = fileFor(sessionId, dir);
124	  try {
125	    const parsed = JSON.parse(fs.readFileSync(file, 'utf8'));
126	    return validateRecord(parsed) ? null : parsed;
127	  } catch (_) {
128	    return null;
129	  }
130	}
131	
132	function removeStatus(sessionId, dir) {
133	  try { fs.unlinkSync(fileFor(sessionId, dir)); return true; } catch (_) { return false; }
134	}
135	
136	module.exports = {
137	  SCHEMA, AGENTS, STATES, SOURCES, REQUIRED,
138	  stateDir, sanitizeSessionId, fileFor,
139	  buildRecord, writeStatus, validateRecord, readSnapshots, readStatus, removeStatus
140	};
