'use strict';
// US-005 验收测试：点击会话行跳回终端。
//
// 全离线：**绝不真跑 osascript**（会抢真实桌面焦点，criteria §6 明列为越界），
// **也不 spawn ps** —— 进程表与执行器一律注入伪造的。
// 断言用户可观测结果：生成的 AppleScript 文本、面板收到的快照行、行内错误条文案。

const assert = require('assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
