    assert.ok(!/\bfetch\s*\(/.test(src), `${f} 用了 fetch`);
    const mods = [...src.matchAll(/require\(['"]([^'"]+)['"]\)/g)].map((m) => m[1]);
    for (const m of mods) {
      assert.ok(m.startsWith('.') || ['fs', 'os', 'path'].includes(m),
        `${f} require 了未披露的模块 ${m}`);
