const failures = [];
// 串行 await：async 用例 fire-and-forget 时断言失败会变成未捕获 rejection，
// 在汇总行之后才炸，屏幕上先显示「全绿」—— 那是把红的显示成绿的（knowledge.md）。
const queue = [];
function test(name, fn) { queue.push({ name, fn }); }

async function runAll() {
  for (const { name, fn } of queue) {
    try {
      await fn();
      passed++;
