test('映射表与 PROTOCOL.md Codex 表逐行一致（表是文档的实现，不是另一套）', () => {
  const md = fs.readFileSync(path.join(ROOT, 'PROTOCOL.md'), 'utf8');
  const section = md.slice(md.indexOf('Codex CLI 事件映射'));
