  const dir = tmp();
  const relay = `
    const { spawnSync } = require('child_process');
    const fx = require('fs').readFileSync(${JSON.stringify(path.join(FIXTURES, 'session-start.json'))}, 'utf8');
    spawnSync(process.execPath, [${JSON.stringify(HOOK)}], { input: fx, encoding: 'utf8' });
